const page_status = this.getValue('page_status');

if (page_status === 'View' || !value) {
    callback();
    return;
}
let organizationId = this.getVarGlobal('deptParentId');
        if(organizationId === '0'){
            organizationId = this.getVarSystem('deptIds').split(',')[0];
        }
db.collection("transfer_order")
    .where({ to_id: value, organization_id: organizationId })
    .get()
    .then(response => {
        const matchingPicking = response.data || [];

        if (matchingPicking.length === 0) {
            callback();
            return;
        }

        if (page_status === 'Edit') {
            const currentPickingId = this.getValue('id');
            const isSamePicking = matchingPicking.some(picking => picking.id === currentPickingId);
            callback(isSamePicking ? undefined : 'Transfer Order No already exists.');
        } else {
            callback('Transfer Order No already exists.');
        }
    })
    .catch(error => {
        console.error("Error checking Transfer Order No.:", error);
        callback("Error validating Transfer Order No.");
    });

