const url = new URL(window.location.href)
const type = url.searchParams.get('type')
const id = url.searchParams.get('id')

if (type && id) {
  this.toView({
    title: type.charAt(0).toUpperCase() + type.slice(1),
    target: '1993515601863524353', //table id for packing
    targetType: 'Table',
    mode: 'drawer',
    ...(type === 'view' ? { viewMode: 'disabled' } : {}),
    type: type,
    data: {
      id: id
    }
  })
}

(async () => {
  const packingList =
    this.getComponent("custom_tp16y9k1")?.$refs.crud.tableSelect;

  console.log("packingList", packingList);
  const plantId = this.getVarSystem("deptIds").split(",")[0];
  let packingIDs;

  if (packingList && packingList.length > 0) {
    packingIDs = packingList.map((item) => item.id);

    console.log("packingIDs", packingIDs);

    this.setData({
      packing_id: packingIDs.join(","),
    });

    const resTemplateAccess = await db
      .collection("print_template_access")
      .filter([
        {
          type: "branch",
          operator: "all",
          children: [
            {
              prop: "plant_id",
              operator: "in",
              value: plantId,
            },
            {
              prop: "doc_type",
              operator: "equal",
              value: "packing",
            },
          ],
        },
      ])
      .get();

    if (!resTemplateAccess || resTemplateAccess.data.length === 0) {
      this.$message.error("No print template found.");
      return;
    } else if (resTemplateAccess && resTemplateAccess.data.length === 1) {
      const templateID = resTemplateAccess.data[0].print_template_id;

      // Combine the selected packing IDs into a single string and open the print page with the template ID and packing IDs as query parameters
      window.open(
        `/sucode/openpage/${templateID}?ids=${packingIDs.join(
          ",",
        )}&type=packing&name=Packing`,
      );
    } else if (resTemplateAccess && resTemplateAccess.data.length > 1) {
      await this.openDialog("dialog_select_template");
      setTimeout(() => {
        this.setData({
          [`dialog_select_template.template_id`]: "",
          [`dialog_select_template.print_template_id`]: "",
          [`dialog_select_template.type`]: "",
        });

        this.setOptionData(
          `dialog_select_template.print_template_id`,
          resTemplateAccess.data,
        );
      }, 50);
    }

    await this.getComponent("custom_tp16y9k1")?.$refs.crud.clearSelection();
  } else {
    this.$message.error("Please select at least one record.");
  }
})();

(async () => {
  const templateID = this.getValue(`dialog_select_template.template_id`);
  const type = this.getValue(`dialog_select_template.type`);
  const packingIDs = this.getValue("packing_id");

  window.open(
    `/sucode/openpage/${templateID}?ids=${packingIDs}&type=packing&name=Packing`,
  );

  this.setData({
    [`dialog_select_template.template_id`]: "",
    [`dialog_select_template.print_template_id`]: "",
  });

  this.closeDialog("dialog_select_template");
})();
